@rx.event(background=True)
async def _poll_metrics(self) -> None:
    """Continuously poll the local metrics endpoint and update state."""
    async with httpx.AsyncClient(timeout=2.0) as client:
        while True:
            try:
                response = await client.get(METRICS_ENDPOINT)
                if response.status_code == 200:
                    data = response.json()
                    # Only mutate state once we actually hold the lock.
                    async with self:
                        self.metrics = data
            except Exception:
                # Polling errors should not crash the dashboard; the next
                # tick will try again.
                pass
            await asyncio.sleep(POLL_INTERVAL_SECONDS)

def start_polling(self) -> None:
    """Kick off the background polling task on page load."""
    return State._poll_metrics

